head.script:
(function () {
  var XHTML_NS =
    "http://www.w3.org/1999/xhtml";

  var foreignObject =
    document.querySelector("foreignObject");

  if (!foreignObject) return;

  var root =
    foreignObject.firstElementChild;

  if (!root) return;

  var originalCreateElement =
    document.createElement.bind(document);

  var originalCreateElementNS =
    document.createElementNS.bind(document);

  try {
    Object.defineProperty(
      document,
      "head",
      {
        get: function () {
          return root.querySelector("head");
        },
        configurable: true
      }
    );

    Object.defineProperty(
      document,
      "body",
      {
        get: function () {
          return root.querySelector("body");
        },
        configurable: true
      }
    );

    Object.defineProperty(
      document,
      "documentElement",
      {
        get: function () {
          return root;
        },
        configurable: true
      }
    );
  } catch (_) {}

  document.createElement =
    function (tag, options) {
      if (typeof tag === "string") {
        return originalCreateElementNS(
          XHTML_NS,
          tag,
          options
        );
      }

      return originalCreateElement(
        tag,
        options
      );
    };

  document.createElementNS =
    function (namespace, name, options) {
      if (
        namespace == null ||
        namespace === XHTML_NS
      ) {
        return originalCreateElementNS(
          XHTML_NS,
          name,
          options
        );
      }

      return originalCreateElementNS(
        namespace,
        name,
        options
      );
    };

  try {
    Object.defineProperty(
      document,
      "getElementById",
      {
        value: function (id) {
          var safe =
            String(id)
              .replace(
                /["\\]/g,
                "\\$&"
              );

          return root.querySelector(
            '[id="' + safe + '"]'
          );
        },

        configurable: true,
        writable: true
      }
    );
  } catch (_) {}

  var originalQuerySelector =
    document.querySelector.bind(document);

  var originalQuerySelectorAll =
    document.querySelectorAll.bind(document);

  document.querySelector =
    function (selector) {
      try {
        return (
          root.querySelector(selector) ||
          originalQuerySelector(selector)
        );
      } catch (_) {
        return originalQuerySelector(
          selector
        );
      }
    };

  document.querySelectorAll =
    function (selector) {
      try {
        var result =
          root.querySelectorAll(selector);

        return result.length
          ? result
          : originalQuerySelectorAll(
              selector
            );
      } catch (_) {
        return originalQuerySelectorAll(
          selector
        );
      }
    };
})();

svg.script:
(function () {
  "use strict";

  var XHTML_NS =
    "http://www.w3.org/1999/xhtml";

  var bootOverlay =
    document.getElementById(
      "synnical-svg-boot-overlay"
    );

  var bootStatus =
    document.getElementById(
      "synnical-svg-boot-status"
    );

  var bootDetail =
    document.getElementById(
      "synnical-svg-boot-detail"
    );

  function setBootStatus(title, detail, failed) {
    try {
      if (bootStatus) {
        bootStatus.textContent =
          String(title || "");
      }

      if (bootDetail) {
        bootDetail.textContent =
          String(detail || "");

        bootDetail.setAttribute(
          "fill",
          failed ? "#ff6b6b" : "#999999"
        );
      }
    } catch (_) {}
  }

  function errorText(value) {
    if (!value) {
      return "Unknown error";
    }

    if (value instanceof Error) {
      return (
        value.name +
        ": " +
        value.message
      ).slice(0, 300);
    }

    return String(value).slice(0, 300);
  }

  window.addEventListener(
    "error",
    function (event) {
      setBootStatus(
        "Synnical SVG boot failed",
        errorText(
          event.error ||
          event.message
        ),
        true
      );
    },
    true
  );

  window.addEventListener(
    "unhandledrejection",
    function (event) {
      setBootStatus(
        "Synnical SVG boot failed",
        errorText(event.reason),
        true
      );
    }
  );

  try {
    var foreignObject =
      document.querySelector(
        "foreignObject"
      );

    if (!foreignObject) {
      throw new Error(
        "foreignObject was not found"
      );
    }

    var htmlRoot =
      foreignObject.firstElementChild;

    if (!htmlRoot) {
      throw new Error(
        "XHTML root was not found"
      );
    }

    var originalCreateElement =
      document.createElement.bind(
        document
      );

    var originalCreateElementNS =
      document.createElementNS.bind(
        document
      );

    document.createElement =
      function (tagName, options) {
        if (
          typeof tagName === "string"
        ) {
          try {
            return originalCreateElementNS(
              XHTML_NS,
              tagName,
              options
            );
          } catch (_) {
            return originalCreateElementNS(
              XHTML_NS,
              tagName
            );
          }
        }

        return originalCreateElement(
          tagName,
          options
        );
      };

    document.createElementNS =
      function (
        namespace,
        tagName,
        options
      ) {
        if (
          namespace == null ||
          namespace === XHTML_NS
        ) {
          try {
            return originalCreateElementNS(
              XHTML_NS,
              tagName,
              options
            );
          } catch (_) {
            return originalCreateElementNS(
              XHTML_NS,
              tagName
            );
          }
        }

        try {
          return originalCreateElementNS(
            namespace,
            tagName,
            options
          );
        } catch (_) {
          return originalCreateElementNS(
            namespace,
            tagName
          );
        }
      };

    try {
      Object.defineProperty(
        document,
        "head",
        {
          configurable: true,
          get: function () {
            return htmlRoot.querySelector(
              "head"
            );
          }
        }
      );
    } catch (_) {}

    try {
      Object.defineProperty(
        document,
        "body",
        {
          configurable: true,
          get: function () {
            return htmlRoot.querySelector(
              "body"
            );
          }
        }
      );
    } catch (_) {}

    try {
      Object.defineProperty(
        document,
        "documentElement",
        {
          configurable: true,
          get: function () {
            return htmlRoot;
          }
        }
      );
    } catch (_) {}

    var nativeGetElementById =
      document.getElementById.bind(
        document
      );

    try {
      document.getElementById =
        function (id) {
          try {
            var safe =
              String(id).replace(
                /["\\]/g,
                "\\$&"
              );

            return (
              htmlRoot.querySelector(
                '[id="' +
                safe +
                '"]'
              ) ||
              nativeGetElementById(id)
            );
          } catch (_) {
            return nativeGetElementById(
              id
            );
          }
        };
    } catch (_) {}

    var appRoot =
      htmlRoot.querySelector("#root");

    if (!appRoot) {
      throw new Error(
        "#root was not found in XHTML"
      );
    }

    setBootStatus(
      "Synnical SVG booting...",
      "Loading Vite application module",
      false
    );

    var bundleUrl =
      new URL(
        "./assets/bundle.js",
        window.location.href
      ).href;

    import(bundleUrl)
      .then(function () {
        setBootStatus(
          "Synnical module loaded",
          "Waiting for React to mount",
          false
        );

        var tries = 0;

        var mountedCheck =
          window.setInterval(
            function () {
              tries += 1;

              var root =
                htmlRoot.querySelector(
                  "#root"
                );

              if (
                root &&
                root.childNodes &&
                root.childNodes.length > 0
              ) {
                window.clearInterval(
                  mountedCheck
                );

                if (bootOverlay) {
                  bootOverlay.setAttribute(
                    "display",
                    "none"
                  );
                }

                return;
              }

              if (tries >= 50) {
                window.clearInterval(
                  mountedCheck
                );

                setBootStatus(
                  "Synnical module loaded",
                  "React did not mount into #root",
                  true
                );
              }
            },
            100
          );
      })
      .catch(function (error) {
        setBootStatus(
          "Synnical module import failed",
          errorText(error),
          true
        );

        console.error(
          "[synnical-svg] bundle import failed",
          error
        );
      });
  } catch (error) {
    setBootStatus(
      "Synnical SVG bootstrap failed",
      errorText(error),
      true
    );

    console.error(
      "[synnical-svg] bootstrap failed",
      error
    );
  }
})();
